            passagesSummary = "1 Samuel 18–20",
            primaryBookId = 9,
            primaryChapter = 18,
            primaryVerse = 1,
            passages = listOf(PlanPassageSegment(9, "1 Samuel", 18), PlanPassageSegment(9, "1 Samuel", 19), PlanPassageSegment(9, "1 Samuel", 20)),
